extends SceneTree

func _init():
	var autoload = preload("res://autoloads/GameSettings.gd").new()
	autoload.name = "GameSettings"
	root.add_child(autoload)

	var scene = preload("res://scenes/RootUI.tscn").instantiate()
	root.add_child(scene)

	scene.get_node("SettingsMenu").visible = true
	Input.action_press("ui_back")

	# pump a frame
	process_frame()

	print("SettingsMenu visible: ", scene.get_node("SettingsMenu").visible)
	print("MainMenu visible: ", scene.get_node("MainMenu").visible)
	quit()

func process_frame():
	for child in root.get_children():
		if child.has_method("_process"):
			child._process(0.016)
		_propagate_process(child)

func _propagate_process(node):
	for child in node.get_children():
		if child.has_method("_process"):
			child._process(0.016)
		_propagate_process(child)
EOF
